[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>EV Charging Network Performance &amp; Grid Optimization Report</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --bg: #0f1117;
    --surface: #1a1d27;
    --surface2: #222638;
    --border: #2e3250;
    --accent: #4f8ef7;
    --accent2: #34d399;
    --accent3: #f59e0b;
    --accent4: #f87171;
    --text: #e2e8f0;
    --text-muted: #8892b0;
    --text-dim: #4a5568;
    --highway: #4f8ef7;
    --urban: #34d399;
    --peak: #f87171;
    --offpeak: #34d399;
  }
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    background: var(--bg);
    color: var(--text);
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    font-size: 14px;
    line-height: 1.6;
  }
  a { color: var(--accent); text-decoration: none; }
  a:hover { text-decoration: underline; }

  /* HEADER */
  .report-header {
    background: linear-gradient(135deg, #0f1117 0%, #1a1d27 50%, #0d1a3a 100%);
    border-bottom: 1px solid var(--border);
    padding: 48px 40px 36px;
    position: relative;
    overflow: hidden;
  }
  .report-header::before {
    content: '';
    position: absolute; top: 0; right: 0; bottom: 0;
    width: 40%;
    background: radial-gradient(ellipse at right center, rgba(79,142,247,0.08) 0%, transparent 70%);
  }
  .header-badge {
    display: inline-block;
    background: rgba(79,142,247,0.15);
    border: 1px solid rgba(79,142,247,0.3);
    color: var(--accent);
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    padding: 4px 12px;
    border-radius: 20px;
    margin-bottom: 16px;
  }
  .report-header h1 {
    font-size: 28px;
    font-weight: 700;
    color: #fff;
    line-height: 1.2;
    max-width: 700px;
    margin-bottom: 10px;
  }
  .report-header .subtitle {
    color: var(--text-muted);
    font-size: 14px;
    max-width: 640px;
    margin-bottom: 24px;
  }
  .header-meta {
    display: flex;
    gap: 24px;
    flex-wrap: wrap;
    font-size: 12px;
    color: var(--text-dim);
  }
  .header-meta span { display: flex; align-items: center; gap: 6px; }
  .dot { width: 6px; height: 6px; border-radius: 50%; background: var(--accent2); display: inline-block; }

  /* NAV */
  .nav-bar {
    background: var(--surface);
    border-bottom: 1px solid var(--border);
    padding: 0 40px;
    display: flex;
    gap: 0;
    overflow-x: auto;
    position: sticky;
    top: 0;
    z-index: 100;
  }
  .nav-bar a {
    display: block;
    padding: 14px 16px;
    font-size: 12px;
    font-weight: 500;
    color: var(--text-muted);
    white-space: nowrap;
    border-bottom: 2px solid transparent;
    transition: color 0.2s, border-color 0.2s;
  }
  .nav-bar a:hover { color: var(--text); border-bottom-color: var(--accent); text-decoration: none; }

  /* LAYOUT */
  .container { max-width: 1280px; margin: 0 auto; padding: 0 40px 60px; }

  /* KPI BANNER */
  .kpi-banner {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
    padding: 32px 0 24px;
  }
  .kpi-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 20px 20px 16px;
    position: relative;
    overflow: hidden;
  }
  .kpi-card::before {
    content: '';
    position: absolute; top: 0; left: 0; right: 0;
    height: 3px;
    background: var(--kpi-color, var(--accent));
    border-radius: 12px 12px 0 0;
  }
  .kpi-label {
    font-size: 11px;
    font-weight: 600;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.8px;
    margin-bottom: 8px;
  }
  .kpi-value {
    font-size: 28px;
    font-weight: 700;
    color: #fff;
    line-height: 1;
    margin-bottom: 6px;
  }
  .kpi-sub { font-size: 11px; color: var(--text-dim); }
  .kpi-trend {
    display: inline-flex;
    align-items: center;
    gap: 3px;
    font-size: 11px;
    font-weight: 600;
    padding: 2px 7px;
    border-radius: 10px;
    margin-top: 6px;
  }
  .trend-up { background: rgba(52,211,153,0.1); color: var(--accent2); }
  .trend-warn { background: rgba(248,113,113,0.1); color: var(--accent4); }
  .trend-neutral { background: rgba(79,142,247,0.1); color: var(--accent); }

  /* SECTIONS */
  .section {
    margin-top: 48px;
    scroll-margin-top: 60px;
  }
  .section-header {
    display: flex;
    align-items: flex-start;
    gap: 14px;
    margin-bottom: 24px;
    padding-bottom: 16px;
    border-bottom: 1px solid var(--border);
  }
  .section-num {
    background: rgba(79,142,247,0.12);
    border: 1px solid rgba(79,142,247,0.25);
    color: var(--accent);
    font-size: 12px;
    font-weight: 700;
    width: 28px; height: 28px;
    border-radius: 8px;
    display: flex; align-items: center; justify-content: center;
    flex-shrink: 0;
    margin-top: 2px;
  }
  .section-title { font-size: 20px; font-weight: 700; color: #fff; }
  .section-objective { font-size: 13px; color: var(--text-muted); margin-top: 4px; }

  /* GRID LAYOUTS */
  .grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
  .grid-3 { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 20px; }
  .grid-1-2 { display: grid; grid-template-columns: 1fr 2fr; gap: 20px; }
  .grid-2-1 { display: grid; grid-template-columns: 2fr 1fr; gap: 20px; }

  /* CHART CARDS */
  .card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 20px;
  }
  .card-title {
    font-size: 13px;
    font-weight: 600;
    color: var(--text);
    margin-bottom: 4px;
  }
  .card-subtitle {
    font-size: 11px;
    color: var(--text-muted);
    margin-bottom: 16px;
  }
